package webpresenter.server.devices;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;
import java.util.UUID;

/** A MediaPlayer known to the server. The id is generated by the player and kept across restarts. */
@Entity
@Table(name = "device")
class Device {

    @Id
    private UUID id;

    @Column(nullable = false)
    private String name;

    @Column(nullable = false)
    private String hostname;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private DeviceStatus status;

    @Column(name = "pairing_code")
    private String pairingCode;

    /** SHA-256 of the device token; the token itself is only known by the player. */
    @Column(name = "token_hash")
    private String tokenHash;

    @Column(name = "player_version")
    private String playerVersion;

    /** Displays last reported by the player, as protocol JSON. */
    @Column(name = "displays_json", nullable = false)
    private String displaysJson;

    @Column(name = "display_index", nullable = false)
    private int displayIndex;

    @Column(name = "rest_media_id")
    private UUID restMediaId;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    @Column(name = "approved_at")
    private Instant approvedAt;

    @Column(name = "approved_by")
    private String approvedBy;

    @Column(name = "last_seen_at", nullable = false)
    private Instant lastSeenAt;

    protected Device() {}

    static Device pending(UUID id, String hostname, String pairingCode, Instant now) {
        Device d = new Device();
        d.id = id;
        d.name = hostname;
        d.hostname = hostname;
        d.status = DeviceStatus.PENDING;
        d.pairingCode = pairingCode;
        d.displaysJson = "[]";
        d.createdAt = now;
        d.lastSeenAt = now;
        return d;
    }

    void reportConnection(String hostname, String playerVersion, String displaysJson, Instant now) {
        this.hostname = hostname;
        this.playerVersion = playerVersion;
        this.displaysJson = displaysJson;
        this.lastSeenAt = now;
    }

    void approve(String name, String tokenHash, String by, Instant now) {
        this.status = DeviceStatus.APPROVED;
        this.name = name;
        this.tokenHash = tokenHash;
        this.pairingCode = null;
        this.approvedBy = by;
        this.approvedAt = now;
    }

    void configure(String name, int displayIndex, UUID restMediaId) {
        this.name = name;
        this.displayIndex = displayIndex;
        this.restMediaId = restMediaId;
    }

    void clearRestMedia() {
        this.restMediaId = null;
    }

    void seen(Instant now) {
        this.lastSeenAt = now;
    }

    UUID id() { return id; }
    String name() { return name; }
    String hostname() { return hostname; }
    DeviceStatus status() { return status; }
    String pairingCode() { return pairingCode; }
    String tokenHash() { return tokenHash; }
    String playerVersion() { return playerVersion; }
    String displaysJson() { return displaysJson; }
    int displayIndex() { return displayIndex; }
    UUID restMediaId() { return restMediaId; }
    Instant createdAt() { return createdAt; }
    Instant approvedAt() { return approvedAt; }
    String approvedBy() { return approvedBy; }
    Instant lastSeenAt() { return lastSeenAt; }
}
